import { isHiddenDimensionField } from "./explore/exploreUtils";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface Props {
  fields: FieldInfo[];
  metricField: string;
  metricType: MetricType;
  aggregation: AggregationType;
  metricNamespace: string | null;
  indexPattern: string;
  timeRange: TimeRange;
  client: ElasticsearchClient | null;
  onSelectDimension: (dimensionField: string) => void;
  onBackToOverview: () => void;
  onViewUngrouped: () => void;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const MAX_SERIES = 5;
const NO_DIMENSIONS_ITEM_NAME = "__no_dimensions__";
const DIMENSION_CARD_SLOT_PREFIX = "metrics-dimension-card";
const NO_DIMENSIONS_SLOT_SUFFIX = "__no_dimensions__";
const DIMENSION_CARD_SYSTEM_PROMPT =
  "You are a metrics observability assistant. " +
  "Generate one concise, high-signal insight per metric dimension card slot. " +
  "For each dimension card, focus on whether split-by is likely useful and why. " +
  "Use plain language and avoid repeating obvious labels." +
  INSIGHT_GUARDRAIL;

function dimensionCardSlotId(metricField: string, dimensionField: string): string {
  return `${DIMENSION_CARD_SLOT_PREFIX}:${metricField}:${dimensionField}`;
}

function getTopDimensionValues(data: EsqlResponse, limit = 5): string[] {
  const lookup = buildColumnLookup(data.columns);
  const dateIdx = findDateColumnIndex(data);
  const metricIdx = getColumnIndex(lookup, "metric");
  const dimIdx = data.columns.findIndex((_, i) => i !== dateIdx && i !== metricIdx);
  if (dimIdx < 0) return [];

  const counts = new Map<string, number>();
  for (const row of data.values) {
    const dimVal = normalizeDimensionBucketLabel(getRowValue(row, dimIdx));
    counts.set(dimVal, (counts.get(dimVal) ?? 0) + 1);
  }
  return Array.from(counts.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([value]) => value);
}

// ---------------------------------------------------------------------------
// Multi-series sparkline option builder
// ---------------------------------------------------------------------------

function buildMultiSeriesSparkline(
  data: EsqlResponse,
  themeOpts: ReturnType<typeof useEChartTheme>,
  legendTextColor: string,
): Record<string, unknown> {
  const lookup = buildColumnLookup(data.columns);
  const dateIdx = findDateColumnIndex(data);
  const metricIdx = getColumnIndex(lookup, "metric");
  // Dimension column is the third column (not timestamp, not metric)
  const dimIdx = data.columns.findIndex((_, i) => i !== dateIdx && i !== metricIdx);

  if (metricIdx < 0) {
    return { title: { text: "No data", left: "center", top: "center" } };
  }

  // Group rows by dimension value
  const grouped = new Map<string, [number | null, unknown][]>();
  for (const row of data.values) {
    const dimVal = dimIdx >= 0 ? normalizeDimensionBucketLabel(getRowValue(row, dimIdx)) : "all";
    const tsValue = getRowValue(row, dateIdx);
    const ts = dateIdx >= 0 && tsValue ? new Date(String(tsValue)).getTime() : null;
    if (!grouped.has(dimVal)) grouped.set(dimVal, []);
    grouped.get(dimVal)!.push([ts, getRowValue(row, metricIdx)]);
  }

  // Take top N series by number of data points (proxy for frequency)
  const sortedKeys = [...grouped.keys()]
    .sort((a, b) => grouped.get(b)!.length - grouped.get(a)!.length)
    .slice(0, MAX_SERIES);

  const totalKeys = grouped.size;

  const colors =
    themeOpts.color.length > 0
      ? themeOpts.color
      : ["#0077CC", "#FF6B6B", "#4ECB71", "#FFD93D", "#6C5CE7"];

  const series = sortedKeys.map((key, i) => ({
    type: "line" as const,
    name: key,
    data: grouped.get(key)!,
    smooth: true,
    showSymbol: false,
    lineStyle: { width: 1.5 },
    areaStyle: { opacity: 0.1 },
    itemStyle: { color: colors[i % colors.length] },
  }));

  return {
    ...themeOpts,
    grid: { left: 4, right: 4, top: 4, bottom: 24, containLabel: false },
    xAxis: { type: "time", show: false },
    yAxis: { type: "value", show: false },
    tooltip: {
      trigger: "axis",
      confine: true,
      textStyle: { fontSize: 11 },
    },
    legend: {
      show: true,
      bottom: 0,
      left: "center",
      type: "scroll",
      itemWidth: 12,
      itemHeight: 8,
      textStyle: { fontSize: 10, color: legendTextColor },
      formatter: (name: string) => {
        const short = name.length > 20 ? name.slice(0, 18) + "..." : name;
        return totalKeys > MAX_SERIES && name === sortedKeys[sortedKeys.length - 1]
          ? `${short} (+${totalKeys - MAX_SERIES})`
          : short;
      },
    },
    series,
  };
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function DimensionOverviewGrid({
  fields,
  metricField,
  metricType,
  aggregation,
  metricNamespace,
  indexPattern,
  timeRange,
  client,
  onSelectDimension,
  onBackToOverview,
  onViewUngrouped,
}: Props) {
  const theme = useTheme();
  const echartsTheme = useEChartTheme();

  // Discover dimension fields — same logic as DimensionSidebar
  const dimensionFields = useMemo(() => {
    const base = fields.filter((f) => isDimensionField(f) && !isHiddenDimensionField(f.name));
    if (metricNamespace === null) return base;
    const scoped = base.filter(
      (f) => f.name === metricNamespace || f.name.startsWith(`${metricNamespace}.`),
    );
    return scoped.length > 0 ? scoped : base;
  }, [fields, metricNamespace]);

  const scopeKey = [
    metricField,
    metricType,
    aggregation,
    indexPattern,
    timeRange.from,
    timeRange.to,
    dimensionFields.map((f) => f.name).join(","),
  ].join("|");

  const buildQuery = useCallback(
    (field: FieldInfo) =>
      buildDimensionOverviewQuery({
        indexPattern,
        metricField,
        metricType,
        aggregation,
        dimensionField: field.name,
        timeRange,
      }),
    [indexPattern, metricField, metricType, aggregation, timeRange],
  );

  const { results, retryFailed } = useBatchedOverviewQueries({
    items: dimensionFields,
    client,
    scopeKey,
    buildQuery,
    timeRange,
  });
  const noDimensionsItems = useMemo(
    () => (dimensionFields.length > 0 ? [{ name: NO_DIMENSIONS_ITEM_NAME }] : []),
    [dimensionFields.length],
  );
  const { results: noDimensionsResults } = useBatchedOverviewQueries({
    items: noDimensionsItems,
    client,
    scopeKey: `${scopeKey}|no-dimensions`,
    buildQuery: () =>
      buildOverviewQuery({
        indexPattern,
        metricField,
        metricType,
        aggregation,
        timeRange,
      }),
    timeRange,
  });
  const noDimensionsResult = noDimensionsResults[NO_DIMENSIONS_ITEM_NAME];
  const noDimensionsHasData = hasOverviewData(noDimensionsResult);

  const dimsWithData = useMemo(() => {
    return dimensionFields.filter((f) => hasOverviewData(results[f.name]));
  }, [dimensionFields, results]);

  const { multiSeriesDims, singleSeriesDims } = useMemo(() => {
    const multi: FieldInfo[] = [];
    const single: FieldInfo[] = [];
    for (const f of dimsWithData) {
      const result = results[f.name];
      if (result?.data) {
        const count = getDimensionSeriesCount(result.data);
        if (count > 1) multi.push(f);
        else single.push(f);
      }
    }
    return { multiSeriesDims: multi, singleSeriesDims: single };
  }, [dimsWithData, results]);

  const failedDims = useMemo(() => {
    return dimensionFields.filter((f) => results[f.name]?.status === "error");
  }, [dimensionFields, results]);

  const failedDimItems: FailedItem[] = useMemo(
    () =>
      failedDims.map((f) => ({
        name: f.name,
        reason: results[f.name]?.errorReason ?? "Unknown error",
      })),
    [failedDims, results],
  );

  const isLoading = useMemo(
    () => dimensionFields.some((f) => results[f.name]?.status === "loading"),
    [dimensionFields, results],
  );

  const handleCardClick = useCallback(
    (fieldName: string) => {
      onSelectDimension(fieldName);
    },
    [onSelectDimension],
  );

  const renderDimensionCard = (field: FieldInfo) => {
    const result = results[field.name];
    const fieldVisual = classifyFieldVisual(field.name, field.metricType);
    const displayName =
      metricNamespace && field.name.startsWith(`${metricNamespace}.`)
        ? field.name.slice(metricNamespace.length + 1)
        : field.name;

    return (
      <Paper
        key={field.name}
        variant="outlined"
        sx={{
          minHeight: 180,
          transition: "border-color 0.15s",
          "&:hover": {
            borderColor: "border.strong",
          },
        }}
      >
        <ButtonBase
          aria-label={`Group by ${field.name}`}
          onClick={() => handleCardClick(field.name)}
          sx={{
            display: "flex",
            flexDirection: "column",
            alignItems: "stretch",
            width: "100%",
            height: "100%",
            p: 1,
            transition: "background-color 0.15s",
            "&.Mui-focusVisible": {
              boxShadow: `0 0 0 2px ${theme.palette.primary.main}`,
            },
          }}
        >
          {/* Card header */}
          <Box sx={{ display: "flex", gap: 0.5, alignItems: "center", mb: 0.5 }}>
            {getFieldVisualIcon(fieldVisual, 12)}
            <Typography
              variant="caption"
              noWrap
              sx={{ flex: 1, fontWeight: 600 }}
              title={field.name}
            >
              {displayName}
            </Typography>
            <Chip
              label={field.type}
              size="small"
              variant="outlined"
              sx={{
                height: 16,
                fontSize: "0.6rem",
              }}
            />
          </Box>

          {/* Multi-series sparkline */}
          <Box sx={{ flex: 1, minHeight: 120 }}>
            {result?.data ? (
              <EChart
                option={buildMultiSeriesSparkline(
                  result.data,
                  echartsTheme,
                  theme.palette.text.primary,
                )}
                theme={echartsTheme}
                sx={{ width: "100%", height: "100%", minHeight: 120 }}
              />
            ) : (
              <Skeleton variant="rounded" height="100%" />
            )}
          </Box>
        </ButtonBase>
      </Paper>
    );
  };

  const shortMetric = metricField.includes(".")
    ? metricField.split(".").slice(-2).join(".")
    : metricField;

  const noDimensionsSlotId = useMemo(
    () => dimensionCardSlotId(metricField, NO_DIMENSIONS_SLOT_SUFFIX),
    [metricField],
  );
  const dimensionCardSlots = useMemo(
    () => [
      {
        slotId: noDimensionsSlotId,
        label: `No dimensions card for metric ${metricField}`,
      },
      ...dimsWithData.map((field) => ({
        slotId: dimensionCardSlotId(metricField, field.name),
        label: `Dimension card for ${field.name} on metric ${metricField}`,
      })),
    ],
    [noDimensionsSlotId, metricField, dimsWithData],
  );
  const dimensionCardContext = useMemo(
    () =>
      JSON.stringify({
        metricField,
        metricType,
        metricNamespace,
        indexPattern,
        noDimensionsCard: {
          slotId: noDimensionsSlotId,
          hasData: noDimensionsHasData,
          rowCount: noDimensionsResult?.data?.values.length ?? 0,
        },
        dimensionCards: dimsWithData.map((field) => {
          const data = results[field.name]?.data;
          return {
            slotId: dimensionCardSlotId(metricField, field.name),
            dimensionField: field.name,
            fieldType: field.type,
            seriesCount: data ? getDimensionSeriesCount(data) : 0,
            rowCount: data?.values.length ?? 0,
            topValues: data ? getTopDimensionValues(data) : [],
          };
        }),
      }),
    [
      metricField,
      metricType,
      metricNamespace,
      indexPattern,
      noDimensionsSlotId,
      noDimensionsHasData,
      noDimensionsResult,
      dimsWithData,
      results,
    ],
  );
  const dimensionCardInsights = usePageSlotInsights({
    context: dimensionCardContext,
    systemPrompt: DIMENSION_CARD_SYSTEM_PROMPT,
    // Keep insights stable across data refreshes; only re-run when card identity changes.
    cacheKey: `dimension-card-slots::${metricField}::${metricType}::${aggregation}`,
    slots: dimensionCardSlots,
    enabled: Boolean(noDimensionsHasData || dimsWithData.length > 0),
  });

  if (dimensionFields.length === 0) {
    return (
      <EmptyState
        heading="No dimension fields found"
        description={`No dimension fields found for ${shortMetric}. Connect more data or adjust your filters.`}
        action={
          <Button size="small" onClick={onViewUngrouped}>
            View ungrouped metric
          </Button>
        }
      />
    );
  }

  return (
    <Box sx={{ display: "flex", flexDirection: "column", height: "100%", overflow: "auto", p: 1 }}>
      {/* Header */}
      <ToolbarRow sx={{ mb: 1 }}>
        <Button size="small" startIcon={<ArrowBackIcon />} onClick={onBackToOverview}>
          Back to overview
        </Button>
        <Typography variant="body2" sx={{ flex: 1 }}>
          {shortMetric} — dimensions
        </Typography>
        {isLoading && <LinearProgress sx={{ flexShrink: 0, width: 80 }} />}
        {!isLoading && (
          <>
            <Chip
              label={`${dimsWithData.length} of ${dimensionFields.length} dimensions with data`}
              size="small"
              variant="outlined"
            />
            {failedDims.length > 0 && (
              <Chip
                label={`${failedDims.length} failed`}
                size="small"
                variant="outlined"
                color="error"
                icon={<ErrorOutlineIcon />}
              />
            )}
          </>
        )}
        <Button size="small" variant="outlined" onClick={onViewUngrouped}>
          View ungrouped
        </Button>
      </ToolbarRow>

      <InsightSlotProvider
        summary={dimensionCardInsights.summary}
        insights={dimensionCardInsights.insights}
        loading={dimensionCardInsights.loading}
        error={dimensionCardInsights.error}
        refresh={dimensionCardInsights.refresh}
      >
        <Box sx={{ mb: 2 }}>
          <Typography
            variant="caption"
            color="text.secondary"
            sx={{ display: "block", mb: 1, textTransform: "uppercase", fontWeight: 600 }}
          >
            No dimensions
          </Typography>
          <InsightSlot slotId={noDimensionsSlotId}>
            <Paper
              variant="outlined"
              sx={{
                minHeight: 180,
                transition: "border-color 0.15s",
                "&:hover": { borderColor: "border.strong" },
              }}
            >
              <ButtonBase
                aria-label="View metric without dimensions"
                onClick={onViewUngrouped}
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "stretch",
                  width: "100%",
                  height: "100%",
                  p: 1.5,
                  textAlign: "left",
                  "&.Mui-focusVisible": {
                    boxShadow: `0 0 0 2px ${theme.palette.primary.main}`,
                  },
                }}
              >
                <Typography variant="caption" sx={{ mb: 0.5, fontWeight: 600 }}>
                  No dimensions
                </Typography>
                <Box sx={{ flex: 1, minHeight: 120 }}>
                  {noDimensionsResult?.status === "loading" ? (
                    <Skeleton variant="rounded" height="100%" />
                  ) : noDimensionsHasData && noDimensionsResult?.data ? (
                    <EChart
                      option={buildMultiSeriesSparkline(
                        noDimensionsResult.data,
                        echartsTheme,
                        theme.palette.text.primary,
                      )}
                      theme={echartsTheme}
                      sx={{ width: "100%", height: "100%", minHeight: 120 }}
                    />
                  ) : (
                    <Typography variant="caption" color="text.secondary">
                      View this metric as a single ungrouped time series.
                    </Typography>
                  )}
                </Box>
              </ButtonBase>
            </Paper>
          </InsightSlot>
        </Box>

        {/* Dimensions with multiple series — higher cardinality, typically more interesting */}
        {multiSeriesDims.length > 0 && (
          <Box sx={{ mb: 2 }}>
            <Typography
              variant="caption"
              color="text.secondary"
              sx={{ display: "block", mb: 1, textTransform: "uppercase", fontWeight: 600 }}
            >
              Multiple series ({multiSeriesDims.length})
            </Typography>
            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
                gap: 1,
              }}
            >
              {multiSeriesDims.map((field) => (
                <InsightSlot key={field.name} slotId={dimensionCardSlotId(metricField, field.name)}>
                  {renderDimensionCard(field)}
                </InsightSlot>
              ))}
            </Box>
          </Box>
        )}

        {/* Dimensions with one series — lower cardinality */}
        {singleSeriesDims.length > 0 && (
          <Box>
            <Typography
              variant="caption"
              color="text.secondary"
              sx={{ display: "block", mb: 1, textTransform: "uppercase", fontWeight: 600 }}
            >
              Single series ({singleSeriesDims.length})
            </Typography>
            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
                gap: 1,
              }}
            >
              {singleSeriesDims.map((field) => (
                <InsightSlot key={field.name} slotId={dimensionCardSlotId(metricField, field.name)}>
                  {renderDimensionCard(field)}
                </InsightSlot>
              ))}
            </Box>
          </Box>
        )}
      </InsightSlotProvider>

      {/* Loading placeholders — show when no data yet */}
      {isLoading && dimsWithData.length === 0 && (
        <Box
          sx={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
            gap: 1,
          }}
        >
          {dimensionFields.slice(0, 6).map((field) => (
            <Paper key={`loading-${field.name}`} variant="outlined" sx={{ minHeight: 180, p: 1 }}>
              <Skeleton variant="rounded" height="100%" />
            </Paper>
          ))}
        </Box>
      )}

      {/* Failed dimensions expandable section */}
      {!isLoading && (
        <OverviewFailedItemsSection
          items={failedDimItems}
          itemLabel="dimension"
          listAriaLabel="Failed dimensions"
          retryTooltip="Retry all failed dimension queries"
          retryLabel="Retry failed"
          onRetry={retryFailed}
        />
      )}

      {/* Empty state after loading */}
      {!isLoading &&
        dimsWithData.length === 0 &&
        failedDims.length === 0 &&
        dimensionFields.length > 0 && (
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              gap: 1,
              justifyContent: "center",
              alignItems: "center",
              py: 4,
            }}
          >
            <Typography variant="body2" color="text.primary">
              No dimensions with data found in the selected time range
            </Typography>
            <Button size="small" onClick={onViewUngrouped}>
              View ungrouped metric
            </Button>
          </Box>
        )}
    </Box>
  );
}
